#include <cstdio>
#include <cctype>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

typedef pair<int, int> point;

const int INFINITY = 1000000000;
const int MAX_SIZE = 11;
const int MAX_NODES = 205;
const int DIRECTIONS_COUNT = 4;
const int delta_y[DIRECTIONS_COUNT] = {-1, 0, 1, 0};
const int delta_x[DIRECTIONS_COUNT] = {0, -1, 0, 1};

int grid_size, time_limit;
char grid[MAX_SIZE][MAX_SIZE], backup[MAX_SIZE][MAX_SIZE];
int start_row, start_col;
int distance_map[MAX_SIZE][MAX_SIZE];
int reachability[MAX_SIZE][MAX_SIZE];
bool reachable[MAX_SIZE][MAX_SIZE];
int total_nodes;
int capacity[MAX_SIZE][MAX_SIZE];
vector<int> adj[MAX_NODES];
int flow_value[MAX_NODES], parent[MAX_NODES];

void first_bfs()
{
    fill((int*)capacity, (int*)capacity + MAX_SIZE * MAX_SIZE, time_limit);
    capacity[start_row][start_col] = 0;
    queue<point> q; q.push(point(start_row, start_col));
    while (!q.empty()) {
        point v = q.front(); int d = capacity[v.first][v.second]; q.pop();
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            point u = point(v.first + delta_y[dir], v.second + delta_x[dir]);
            if (0 <= u.first && u.first < grid_size && 0 <= u.second && u.second < grid_size && grid[u.first][u.second] != 'Y' && d + 1 < capacity[u.first][u.second])
                capacity[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void second_bfs(int sr, int sc)
{
    fill((int*)distance_map, (int*)distance_map + MAX_SIZE * MAX_SIZE, INFINITY);
    distance_map[sr][sc] = 0;
    fill((bool*)reachable, (bool*)reachable + MAX_SIZE * MAX_SIZE, false);
    reachable[sr][sc] = true;
    queue<point> q; q.push(point(sr, sc));
    while (!q.empty()) {
        point v = q.front(); int d = distance_map[v.first][v.second]; q.pop();
        reachable[v.first][v.second] = d <= capacity[v.first][v.second];
        if (d >= capacity[v.first][v.second]) continue;
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            point u = point(v.first + delta_y[dir], v.second + delta_x[dir]);
            if (0 <= u.first && u.first < grid_size && 0 <= u.second && u.second < grid_size && grid[u.first][u.second] != 'Y' && d + 1 < distance_map[u.first][u.second])
                distance_map[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void run_bfs(int sr, int sc, int dist[][MAX_SIZE], int INF_VAL)
{
    fill((int*)dist, (int*)dist + MAX_SIZE * MAX_SIZE, INF_VAL);
    dist[sr][sc] = 0;
    queue<point> q; q.push(point(sr, sc));
    while (!q.empty()) {
        point v = q.front(); int d_v = dist[v.first][v.second]; q.pop();
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            point u = point(v.first + delta_y[dir], v.second + delta_x[dir]);
            if (0 <= u.first && u.first < grid_size && 0 <= u.second && u.second < grid_size && grid[u.first][u.second] != 'Y' && d_v + 1 < dist[u.first][u.second])
                dist[u.first][u.second] = d_v + 1, q.push(u);
        }
    }
}

int compute_max_flow()
{
    fill(flow_value, flow_value + total_nodes, 0); flow_value[0] = INFINITY;
    priority_queue<point> pq; pq.push(point(INFINITY, 0));
    while (!pq.empty()) {
        int v = pq.top().second, f = pq.top().first; pq.pop();
        if (flow_value[v] != f) continue;
        for (size_t i = 0; i < adj[v].size(); i++) {
            int u = adj[v][i];
            if (min(f, capacity[v][u]) > flow_value[u]) flow_value[u] = min(f, capacity[v][u]), parent[u] = v, pq.push(point(flow_value[u], u));
        }
    }
    int v = total_nodes - 1;
    if (flow_value[v] == 0) return 0;
    int total_flow = flow_value[v];
    while (v != 0) {
        int u = parent[v];
        capacity[u][v] -= total_flow; capacity[v][u] += total_flow;
        v = u;
    }
    return total_flow;
}

int main()
{
    scanf("%d %d", &grid_size, &time_limit);
    for (int i = 0; i < grid_size; i++)
        for (int j = 0; j < grid_size; j++) {
            scanf(" %c", &grid[i][j]);
            if (grid[i][j] == 'Z') { start_row = i; start_col = j; }
        }
    for (int i = 0; i < grid_size; i++)
        for (int j = 0; j < grid_size; j++)
            scanf(" %c", &backup[i][j]);
    first_bfs();
    total_nodes = 2 * grid_size * grid_size + 2;
    for (int i = 0; i < grid_size; i++)
        for (int j = 0; j < grid_size; j++) if (isdigit(grid[i][j]) && grid[i][j] > '0') {
            int v = i * grid_size + j + 1; capacity[0][v] = grid[i][j] - '0'; adj[0].push_back(v); adj[v].push_back(0);
            second_bfs(i, j);
            for (int i2 = 0; i2 < grid_size; i2++)
                for (int j2 = 0; j2 < grid_size; j2++) if (reachable[i2][j2] && isdigit(backup[i2][j2]) && backup[i2][j2] > '0') {
                    int u = grid_size * grid_size + i2 * grid_size + j2 + 1; capacity[v][u] = INFINITY; adj[v].push_back(u); adj[u].push_back(v);
                }
        }
    for (int i = 0; i < grid_size; i++)
        for (int j = 0; j < grid_size; j++) if (isdigit(backup[i][j]) && backup[i][j] > '0') {
            int u = grid_size * grid_size + i * grid_size + j + 1; capacity[u][total_nodes - 1] = backup[i][j] - '0'; adj[u].push_back(total_nodes - 1); adj[total_nodes - 1].push_back(u);
        }
    int flow;
    int total_flow_value = 0;
    while ((flow = compute_max_flow()) != 0) total_flow_value += flow;
    printf("%d\n", total_flow_value);
    return 0;
}
